import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, LineChart, Line, AreaChart, Area } from 'recharts';
import { TrendingUp, TrendingDown, Download, Activity, Award, Target } from 'lucide-react';
import { DayData } from '../types';

interface ReportsProps {
  calendarData: DayData[];
  onExport: () => void;
}

const CAT_COLORS: Record<string, string> = {
  'Morning Routine': '#F59E0B',
  'English Learning': '#22D3EE',
  'Trading': '#10B981',
  'Coding/DSA': '#8B5CF6',
  'Flutter/React': '#4F8EF7',
  'Night Review': '#6366F1',
};

const CustomTooltip = ({ active, payload, label }: any) => {
  if (!active || !payload?.length) return null;
  return (
    <div style={{ background: '#0D1120', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 12, padding: '12px 16px', backdropFilter: 'blur(20px)' }}>
      <p style={{ fontSize: 11, fontWeight: 700, color: '#64748B', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: 6 }}>{label}</p>
      {payload.map((p: any) => (
        <p key={p.name} style={{ fontSize: 13, fontWeight: 700, color: p.color || '#4F8EF7' }}>{p.value}{p.name === 'completion' ? '%' : ' pts'}</p>
      ))}
    </div>
  );
};

const Reports: React.FC<ReportsProps> = ({ calendarData, onExport }) => {
  const done = calendarData.filter(d => d.completed);
  const last14 = done.slice(-14);

  const chartData = last14.map(d => ({
    name: `D${d.day}`,
    completion: Math.round((d.tasks.filter(t => t.completed).length / d.tasks.length) * 100),
    points: Math.max(0, d.points),
  }));

  const weeklyAvg = chartData.length ? Math.round(chartData.reduce((s, d) => s + d.completion, 0) / chartData.length) : 0;

  const catStats = Object.keys(CAT_COLORS).map(cat => {
    const total = done.reduce((s, d) => s + d.tasks.filter(t => t.category === cat).length, 0);
    const comp = done.reduce((s, d) => s + d.tasks.filter(t => t.category === cat && t.completed).length, 0);
    return { cat, pct: total ? Math.round((comp / total) * 100) : 0, color: CAT_COLORS[cat] };
  });

  // Heatmap: last 90 days
  const heatCells = Array.from({ length: 90 }, (_, i) => {
    const d = calendarData[i];
    if (!d) return { pct: 0, day: i + 1 };
    const pct = d.completed ? Math.round((d.tasks.filter(t => t.completed).length / d.tasks.length) * 100) : 0;
    return { pct, day: d.day };
  });

  const getHeatColor = (pct: number) => {
    if (pct === 0) return 'rgba(255,255,255,0.04)';
    if (pct >= 95) return '#10B981';
    if (pct >= 70) return '#4F8EF7';
    if (pct >= 40) return '#6366F144';
    return '#F8717133';
  };

  return (
    <div style={{ padding: '32px 36px', maxWidth: 1300, margin: '0 auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', marginBottom: 32, flexWrap: 'wrap', gap: 16 }}>
        <div>
          <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 8 }}>Performance Deep-Dive</div>
          <h1 style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 42, fontWeight: 700, color: '#F1F5F9', letterSpacing: '-0.02em' }}>Analytics</h1>
        </div>
        <button onClick={onExport} className="btn-ghost" style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '12px 20px', borderRadius: 14, fontSize: 13 }}>
          <Download size={16} /> Export JSON
        </button>
      </div>

      {/* KPI Row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 16, marginBottom: 32 }}>
        {[
          { label: 'Days Completed', value: done.length,    color: '#10B981', icon: Award,      sub: `of ${calendarData.length} total` },
          { label: 'Weekly Avg',     value: `${weeklyAvg}%`, color: '#4F8EF7', icon: TrendingUp, sub: 'completion rate'                 },
          { label: 'Best Category',  value: catStats.sort((a,b)=>b.pct-a.pct)[0]?.cat.split('/')[0] || '—', color: '#8B5CF6', icon: Target, sub: `${catStats.sort((a,b)=>b.pct-a.pct)[0]?.pct}% done` },
          { label: 'Total Points',   value: done.reduce((s,d)=>s+Math.max(0,d.points),0), color: '#F59E0B', icon: Activity, sub: 'accumulated' },
        ].map(k => {
          const KIcon = k.icon;
          return (
            <div key={k.label} className="card-static" style={{ padding: '22px 24px' }}>
              <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 14 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.1em', textTransform: 'uppercase' }}>{k.label}</div>
                <div style={{ width: 32, height: 32, borderRadius: 10, background: `${k.color}15`, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <KIcon size={16} color={k.color} />
                </div>
              </div>
              <div style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 30, fontWeight: 700, color: k.color, lineHeight: 1, marginBottom: 4 }}>{k.value}</div>
              <div style={{ fontSize: 11, color: '#334155' }}>{k.sub}</div>
            </div>
          );
        })}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 360px', gap: 28 }}>
        {/* Left column */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 28 }}>
          {/* Bar Chart */}
          <div className="card-static" style={{ padding: '24px 28px' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24 }}>
              <div>
                <div style={{ fontSize: 13, fontWeight: 700, color: '#F1F5F9' }}>Daily Completion (Last 14 Days)</div>
                <div style={{ fontSize: 11, color: '#475569', marginTop: 3 }}>Percentage of tasks completed per day</div>
              </div>
              <div style={{ padding: '4px 12px', borderRadius: 99, background: 'rgba(79,142,247,0.1)', border: '1px solid rgba(79,142,247,0.2)', fontSize: 12, fontWeight: 700, color: '#4F8EF7' }}>
                {weeklyAvg}% AVG
              </div>
            </div>
            <div style={{ height: 220 }}>
              {chartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} barSize={24}>
                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.04)" vertical={false} />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#475569', fontSize: 11, fontWeight: 600 }} />
                    <YAxis domain={[0,100]} axisLine={false} tickLine={false} tick={{ fill: '#475569', fontSize: 11 }} />
                    <Tooltip content={<CustomTooltip />} />
                    <Bar dataKey="completion" name="completion" radius={[6,6,0,0]}>
                      {chartData.map((entry, i) => (
                        <Cell key={i} fill={entry.completion >= 80 ? '#4F8EF7' : entry.completion >= 50 ? '#6366F1' : '#F87171'} fillOpacity={0.85} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              ) : (
                <div style={{ height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#334155', fontSize: 14 }}>
                  Complete some days to see analytics!
                </div>
              )}
            </div>
          </div>

          {/* Heatmap */}
          <div className="card-static" style={{ padding: '24px 28px' }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: '#F1F5F9', marginBottom: 6 }}>Contribution Heatmap</div>
            <div style={{ fontSize: 11, color: '#475569', marginBottom: 20 }}>180-day journey — darker = higher completion</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(30, 1fr)', gap: 4 }}>
              {heatCells.map((cell, i) => (
                <div
                  key={i}
                  className="heatmap-cell"
                  title={`Day ${cell.day}: ${cell.pct}%`}
                  style={{ background: getHeatColor(cell.pct), boxShadow: cell.pct >= 95 ? '0 0 6px rgba(16,185,129,0.5)' : 'none' }}
                />
              ))}
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 14, flexWrap: 'wrap' }}>
              <span style={{ fontSize: 10, color: '#334155', fontWeight: 600 }}>Less</span>
              {['rgba(255,255,255,0.04)', '#6366F133', '#4F8EF7', '#10B981'].map((c, i) => (
                <div key={i} style={{ width: 12, height: 12, borderRadius: 3, background: c }} />
              ))}
              <span style={{ fontSize: 10, color: '#334155', fontWeight: 600 }}>More</span>
            </div>
          </div>
        </div>

        {/* Right column */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
          {/* Category Breakdown */}
          <div className="card-static" style={{ padding: '22px 24px' }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: '#F1F5F9', marginBottom: 20 }}>Category Mastery</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              {catStats.sort((a,b) => b.pct - a.pct).map(({ cat, pct, color }) => (
                <div key={cat}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <div style={{ width: 8, height: 8, borderRadius: '50%', background: color, boxShadow: `0 0 6px ${color}` }} />
                      <span style={{ fontSize: 12, fontWeight: 600, color: '#94A3B8' }}>{cat}</span>
                    </div>
                    <span style={{ fontSize: 13, fontWeight: 800, color: color }}>{pct}%</span>
                  </div>
                  <div className="progress-bar-track" style={{ height: 6 }}>
                    <div className="progress-bar-fill" style={{ width: `${pct}%`, background: color, boxShadow: pct > 80 ? `0 0 8px ${color}` : 'none' }} />
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Recent days */}
          <div className="card-static" style={{ padding: '22px 24px', flex: 1, overflowY: 'auto', maxHeight: 380 }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: '#F1F5F9', marginBottom: 16 }}>Recent Days</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {done.slice().reverse().slice(0, 20).map(day => {
                const pct = Math.round((day.tasks.filter(t => t.completed).length / day.tasks.length) * 100);
                const gradeColor = day.grade === 'A+' || day.grade === 'A' ? '#10B981' : day.grade === 'B' ? '#4F8EF7' : day.grade === 'C' ? '#F59E0B' : '#F87171';
                return (
                  <div key={day.day} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 14px', borderRadius: 12, background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.04)', transition: 'all 0.2s' }}
                    onMouseEnter={e => { (e.currentTarget as HTMLElement).style.background = 'rgba(255,255,255,0.05)'; }}
                    onMouseLeave={e => { (e.currentTarget as HTMLElement).style.background = 'rgba(255,255,255,0.02)'; }}
                  >
                    <div style={{ width: 36, height: 36, borderRadius: 10, background: `${gradeColor}15`, border: `1px solid ${gradeColor}33`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 13, fontWeight: 800, color: gradeColor, fontFamily: "'Space Grotesk',sans-serif", flexShrink: 0 }}>
                      {day.grade}
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 12, fontWeight: 700, color: '#94A3B8' }}>Day {day.day}</div>
                      <div style={{ width: '100%', height: 3, background: 'rgba(255,255,255,0.05)', borderRadius: 99, marginTop: 4, overflow: 'hidden' }}>
                        <div style={{ width: `${pct}%`, height: '100%', background: gradeColor, borderRadius: 99 }} />
                      </div>
                    </div>
                    <span style={{ fontSize: 11, fontWeight: 700, color: gradeColor, flexShrink: 0 }}>{pct}%</span>
                  </div>
                );
              })}
              {done.length === 0 && (
                <div style={{ textAlign: 'center', padding: 32, color: '#334155', fontSize: 13 }}>
                  No days completed yet. Get to work!
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Reports;
